import{_ as e,o as t,c as s,a5 as n}from"./chunks/framework.DrDMl0tG.js";const m=JSON.parse('{"title":"Benchmark Example: ANYmal Standing","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/benchmark/anymal_standing_benchmark.md","filePath":"sections/examples/benchmark/anymal_standing_benchmark.md"}'),i={name:"sections/examples/benchmark/anymal_standing_benchmark.md"};function l(o,a,r,d,h,c){return t(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="benchmark-example-anymal-standing" tabindex="-1">Benchmark Example: ANYmal Standing <a class="header-anchor" href="#benchmark-example-anymal-standing" aria-label="Permalink to &quot;Benchmark Example: ANYmal Standing&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Headless timing run for the ANYmal PD-standing contact workload. It prints the simulation throughput and the average number of contacts.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>anymal_standing_benchmark</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run it on one thread for benchmark comparisons:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OMP_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENBLAS_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./build-examples/examples/anymal_standing_benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fast</span></span></code></pre></div><p>On Windows, run <code>anymal_standing_benchmark.exe</code> instead. The example does not use RaisimServer.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ul><li><code>--steps N</code> or <code>--loops N</code> sets the number of integration steps (default 1,000,000).</li><li><code>--fast</code> or <code>--quick</code> caps the step count at 20,000 for smoke tests; an explicit <code>--steps</code> still takes precedence.</li><li><code>ANYMAL_STEPS</code> sets the default step count from the environment.</li><li><code>RAISIM_ANYMAL_PHASE_PROFILE=1</code> also prints the average <code>integrate1</code> and <code>integrate2</code> time per step.</li></ul><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Uses the packaged ANYmal URDF under <code>rsc/anymal</code>.</li><li>Disables sleeping so the measured workload stays active for the whole run.</li></ul>',13)])])}const k=e(i,[["render",l]]);export{m as __pageData,k as default};
